<script setup lang="ts">
import {reactive} from 'vue'
import {useOrderDetail} from '../hooks/useOrderDetail'
import {actionNames,reviewNames,time,money,urgencyName} from '../services/labels'
import StatusTag from '../components/StatusTag.vue'
import MediaPreview from '../components/MediaPreview.vue'
import OrderSteps from '../components/OrderSteps.vue'
const vm=reactive(useOrderDetail())
</script>
<template><section class="page detail-page"><div class="detail-refresh"><a-button type="text" size="small" @click="vm.load">刷新</a-button></div><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon /><a-spin :spinning="vm.loading"><template v-if="vm.order"><OrderSteps :status="vm.order.status" /><div class="panel detail-summary"><div class="card-heading"><span class="category-tag">{{vm.order.categoryName}}</span><StatusTag :status="vm.order.status" /></div><strong class="detail-order-number">{{vm.order.number}}</strong><h2>{{vm.order.description||vm.order.title}}</h2><p>{{vm.order.businessProjectName}}</p></div>
 <div class="panel"><h2>报事信息</h2><dl class="detail-fields"><dt>报事分类</dt><dd>{{vm.order.categoryName}}</dd><dt>报事渠道</dt><dd>{{vm.order.channelName}}</dd><dt>有偿报事</dt><dd>{{vm.order.paid?'是':'否'}}</dd><dt>报事来源</dt><dd>{{vm.order.reportSource===2?'业主报事':'物业自查'}}</dd><dt>报事人</dt><dd>{{vm.order.contactName}}</dd><dt>联系电话</dt><dd><a :href="'tel:'+vm.order.contactPhone">{{vm.order.contactPhone}}</a></dd><dt>报事位置</dt><dd>{{vm.order.positionType===2?'室内':'公区'}} · {{vm.order.spaceName||'—'}}</dd><dt>详细位置</dt><dd>{{vm.order.location||'—'}}</dd><dt>标签</dt><dd>{{vm.order.labelNames?.join('、')||'—'}}</dd><dt>关联设备</dt><dd>{{vm.order.deviceName||'—'}}</dd><dt>登记人</dt><dd>{{vm.order.creatorName||vm.order.reporterName||'—'}}</dd><dt>报事时间</dt><dd>{{time(vm.order.createTime)}}</dd><dt>责任人</dt><dd>{{vm.order.assignedUserName||'待分派'}}</dd><dt>紧急程度</dt><dd>{{urgencyName(vm.order.urgency)}}</dd><dt>报事等级</dt><dd>{{vm.order.levelName||'—'}}</dd><dt>完成时限</dt><dd>{{time(vm.order.finishDeadline)}}</dd><dt>处理时长</dt><dd>{{vm.duration}}</dd><dt>完成时间</dt><dd>{{time(vm.order.finishTime)}}</dd><dt>超时状态</dt><dd>{{vm.order.timedOut===undefined?'—':vm.order.timedOut?'已超时':'未超时'}}</dd><template v-if="vm.order.archiveTime"><dt>归档时间</dt><dd>{{time(vm.order.archiveTime)}}</dd></template><template v-if="vm.order.abandonTime"><dt>废弃时间</dt><dd>{{time(vm.order.abandonTime)}}</dd></template><template v-if="vm.order.abandonReason"><dt>废弃原因</dt><dd>{{vm.order.abandonReason}}</dd></template></dl><div class="attachment-links"><a-button v-for="(id,i) in vm.order.attachmentIds" :key="id" @click="vm.openPreview(id)">报事附件 {{i+1}}</a-button></div></div>
 <div v-if="vm.order.paid" class="panel"><h2>有偿服务</h2><dl class="detail-fields"><dt>材料费</dt><dd>¥ {{money(vm.order.materialAmount)}}</dd><dt>人工费</dt><dd>¥ {{money(vm.order.artificialAmount)}}</dd><dt>合计</dt><dd>¥ {{money(vm.order.totalAmount)}}</dd><dt>业主签字</dt><dd><button v-if="vm.order.signatureFileId" class="text-button" @click="vm.openPreview(vm.order.signatureFileId)">查看签字</button><span v-else>尚未签字</span></dd><dt>签字业主</dt><dd>{{vm.order.signatureOwnerName||'—'}}</dd><dt>签字登记人</dt><dd>{{vm.order.signatureRecorderName||'—'}}</dd></dl></div>
 <div v-if="vm.reviews.length" class="panel"><h2>审核记录</h2><article v-for="review in vm.reviews" :key="review.id" class="review-record"><div class="card-heading"><strong>{{reviewNames[review.kind]}}</strong><span>{{['','待审核','通过','不通过'][review.status]}}</span></div><p>{{review.reason}}</p><p v-if="review.opinion">意见：{{review.opinion}}</p><p v-if="review.refuseReason">不通过原因：{{review.refuseReason}}</p><small>{{review.applicantName}} · {{time(review.createTime)}}</small></article></div>
 <div class="panel"><h2>处理过程</h2><a-timeline><a-timeline-item v-for="process in vm.history" :key="process.id"><div class="card-heading"><strong>{{actionNames[process.action]||process.action}}</strong><small>{{time(process.createTime)}}</small></div><p>{{process.actorName}}</p><p class="process-text">{{process.description}}</p><p v-if="process.details?.reason">{{process.details.reason}}</p><p v-if="process.details?.reply">{{process.details.reply}}</p><p v-if="process.details?.satisfactionId">{{process.details.satisfaction}} 分</p><p v-if="process.details?.ownerName">业主：{{process.details.ownerName}}</p><div class="attachment-links"><a-button v-for="(id,index) in process.attachmentIds" :key="id" size="small" @click="vm.openPreview(id)">附件 {{index+1}}</a-button></div></a-timeline-item></a-timeline></div>
 <div v-if="vm.actions.length" class="action-dock"><a-button v-for="action in vm.actions" :key="action" :type="['accept','follow','finish','dispatch','review'].includes(action)?'primary':'default'" :danger="action==='abandonApply'" @click="vm.perform(action)">{{actionNames[action]}}</a-button></div>
 </template></a-spin><MediaPreview :preview="vm.preview" @close="vm.closePreview" /></section></template>
